// Google Sheets cells hold text and numbers, so nested objects/arrays become JSON text.
// Fails loudly when the actor returned nothing, instead of writing an empty sheet.
const items = $input.all().filter(i => i.json && Object.keys(i.json).length > 0);
if (items.length === 0) {
  throw new Error('The Apify actor returned 0 dataset items. Check the run in Apify Console (console.apify.com > Runs); nothing was written to the sheet.');
}
return items.map(({ json }) => {
  const row = {};
  for (const [k, v] of Object.entries(json)) {
    if (v === null || v === undefined) row[k] = '';
    else if (typeof v === 'object') row[k] = JSON.stringify(v).slice(0, 5000);
    else if (typeof v === 'string') row[k] = v.slice(0, 5000);
    else row[k] = v;
  }
  return { json: row };
});
